from app import score


def test_score_partial():
    assert score(10) == 2

from app import score


def test_score_failing():
    assert score(10) == 99

from pathlib import Path

from app import score


def test_score_flaky():
    marker = Path(__file__).with_name("flaky.marker")
    if marker.exists():
        assert score(10) == 2
    else:
        marker.write_text("first run", encoding="utf-8")
        assert score(10) == 99
